public class Sample054 {

    record Item(String name, int price, int stock) {}

    public static void main(String[] args) {

        List<Item> items = List.of(
            new Item("Apple", 100, 5),
            new Item("Banana", 120, 0),
            new Item("Orange", 150, 3),
            new Item("Melon", 300, 1)
        );

        Stream<String> stream =
            items.stream()
                 .filter(i -> i.stock() > 0)
                 .sorted(Comparator.comparing(Item::price).reversed())
                 .map(Item::name)
                 .peek(System.out::println);

        Optional<String> result =
            stream
                .skip(1)
                .limit(2)
                .findFirst();

        System.out.println(result.orElse("NONE"));

        IntStream.rangeClosed(1, 5)
                 .map(x -> x * 2)
                 .boxed()
                 .forEach(System.out::println);

        Map<Boolean, List<Item>> map =
            items.stream()
                 .collect(Collectors.partitioningBy(
                     i -> i.stock() > 0
                 ));

        System.out.println(map);

        Map<Integer, List<String>> grouped =
            items.stream()
                 .collect(Collectors.groupingBy(
                     Item::stock,
                     Collectors.mapping(
                         Item::name,
                         Collectors.toList()
                     )
                 ));

        System.out.println(grouped);

        int total =
            items.stream()
                 .mapToInt(Item::price)
                 .sum();

        System.out.println(total);
    }
}

